    'nb_w2_3': {
      'en': 'Breaking the balance is your opponent\'s job. You just restore it.',
      'ko': '다르게 만드는 건 상대 몫이야. 넌 다시 똑같이만 해.',
      'ja': '崩すのは相手の役目。あなたはまた同じに戻すだけでいい。',
      'zh': '打破平衡是对手的事,你只管重新弄成一样就行。',
      'es': 'Romper el equilibrio es trabajo del oponente. Tú solo lo restauras.',
