    'nb_w9_title': {
      'en': 'Counting chains',
      'ko': '사슬 세기',
      'ja': '鎖を数える',
      'zh': '数链',
      'es': 'Contar cadenas',
      'pt': 'Contando correntes',
      'de': 'Ketten zählen',
      'fr': 'Compter les chaînes',
      'id': 'Menghitung rantai',
      'vi': 'Đếm chuỗi',
    },
    'nb_w9_1': {
      'en': 'Give one box, get two — the "double-cross".',
      'ko': '상자 하나 주고 두 개 받기 — \'더블 크로스\'.',
      'ja': '箱一つあげて二つもらう — 「ダブルクロス」。',
      'zh': '给一个盒子,换回两个——"双十字"。',
      'es': 'Da una caja, recibe dos — el "doble cruce".',
      'pt': 'Dê uma caixa, receba duas — o "cruzamento duplo".',
      'de': 'Eine Box geben, zwei bekommen — der „Double-Cross".',
      'fr': 'Donne une case, reçois-en deux — le « double-cross ».',
      'id': 'Kasih satu kotak, dapat dua balik — "double-cross".',
      'vi': 'Cho đi một ô, nhận lại hai — "double-cross".',
    },
    'nb_w9_2': {
      'en': 'Don\'t eat a long chain whole. Leave the last two so I have to open the next chain.',
      'ko': '긴 사슬을 통째로 먹지 마. 마지막 둘은 남겨서 다음 사슬도 상대가 열게.',
      'ja': '長い鎖を丸ごと取らないで。最後の二つを残して、次の鎖も私に開けさせて。',
      'zh': '别把长链整条吃掉。留最后两格,好让我不得不打开下一条链。',
      'es': 'No te comas una cadena larga entera. Deja las últimas dos para que yo tenga que abrir la siguiente.',
      'pt': 'Não coma uma corrente longa inteira. Deixe as últimas duas para que eu tenha que abrir a próxima.',
      'de': 'Iss eine lange Kette nicht komplett auf. Lass die letzten zwei übrig, damit ich die nächste Kette öffnen muss.',
      'fr': 'Ne mange pas une longue chaîne en entier. Laisse les deux dernières cases pour que je doive ouvrir la chaîne suivante.',
      'id': 'Jangan makan rantai panjang sampai habis. Sisakan dua terakhir, biar aku terpaksa buka rantai berikutnya.',
      'vi': 'Đừng ăn hết cả một chuỗi dài. Để lại hai ô cuối, để tớ buộc phải mở chuỗi tiếp theo.',
    },
    'nb_w9_3': {
      'en': 'Dots plus long chains: odd or even decides the game.',
      'ko': '점 수 + 긴 사슬 수의 홀짝이 승패를 가른다.',
      'ja': '点の数+長い鎖の数の偶奇が勝敗を分ける。',
      'zh': '点数加长链数的奇偶决定胜负。',
      'es': 'Puntos más cadenas largas: par o impar decide el juego.',
      'pt': 'Pontos mais correntes longas: par ou ímpar decide o jogo.',
      'de': 'Punkte plus lange Ketten: gerade oder ungerade entscheidet das Spiel.',
      'fr': 'Points plus longues chaînes : pair ou impair décide de la partie.',
      'id': 'Jumlah titik ditambah rantai panjang: genap atau ganjil yang menentukan hasil.',
      'vi': 'Số điểm cộng số chuỗi dài: chẵn hay lẻ sẽ quyết định thắng thua.',
    },
    'nb_w10_title': {
      'en': 'Dodging triangles',
      'ko': '삼각형 피하기',
      'ja': '三角形を避ける',
      'zh': '躲避三角形',
      'es': 'Esquivar triángulos',
      'pt': 'Desviando de triângulos',
      'de': 'Dreiecken ausweichen',
      'fr': 'Éviter les triangles',
      'id': 'Menghindari segitiga',
      'vi': 'Né tam giác',
    },
    'nb_w10_1': {
      'en': 'Avoid letting your lines meet. Three of yours at one dot is danger.',
      'ko': '내 선끼리 만나는 점을 줄여. 한 점에 내 선 3개면 위험.',
      'ja': '自分の線同士が交わる点を減らして。一点に自分の線が3本だと危険。',
      'zh': '减少自己的线相交的点。一个点上有3条自己的线就危险了。',
      'es': 'Evita que tus líneas se encuentren. Tres de las tuyas en un punto es peligro.',
      'pt': 'Evite que suas linhas se encontrem. Três suas em um ponto é perigo.',
      'de': 'Vermeide, dass sich deine Linien treffen. Drei von deinen an einem Punkt ist gefährlich.',
      'fr': 'Évite que tes lignes se croisent. Trois des tiennes en un point, c\'est dangereux.',
      'id': 'Hindari garis-garismu bertemu satu sama lain. Tiga garismu di satu titik itu bahaya.',
      'vi': 'Tránh để các đường của cậu gặp nhau. Ba đường của cậu tại một điểm là nguy hiểm.',
    },
    'nb_w10_2': {
      'en': 'Filling between the opponent\'s lines is safe — it can\'t become your triangle.',
      'ko': '상대 색 선 사이를 채우는 건 안전 — 내 삼각형이 될 수 없으니까.',
      'ja': '相手の色の線の間を埋めるのは安全 — 私の三角形にはなり得ないから。',
      'zh': '填在对方颜色的线之间是安全的——因为不可能变成我的三角形。',
      'es': 'Rellenar entre las líneas del oponente es seguro — no puede convertirse en tu triángulo.',
      'pt': 'Preencher entre as linhas do oponente é seguro — não pode virar seu triângulo.',
      'de': 'Zwischen den gegnerischen Linien auszufüllen ist sicher — daraus kann kein Dreieck von dir werden.',
      'fr': 'Remplir entre les lignes de l\'adversaire est sûr — ça ne peut pas devenir ton triangle.',
      'id': 'Mengisi di antara garis lawan itu aman — tidak mungkin jadi segitigamu.',
      'vi': 'Tô giữa các đường của đối thủ là an toàn — vì không thể trở thành tam giác của cậu.',
    },
    'nb_w10_3': {
      'en': 'The second player has the edge here. That\'s why I draw first.',
      'ko': '이 게임은 후공이 유리해. 그래서 내가 먼저 그어놓는 거야.',
      'ja': 'このゲームは後手が有利。だから私が先に線を引いておくの。',
      'zh': '这个游戏是后手有利。所以我才先画。',
      'es': 'En este juego, el segundo jugador tiene ventaja. Por eso trazo primero.',
      'pt': 'Neste jogo, o segundo jogador tem vantagem. Por isso eu traço primeiro.',
      'de': 'Bei diesem Spiel hat der zweite Spieler den Vorteil. Deshalb zeichne ich zuerst.',
      'fr': 'Dans ce jeu, le second joueur a l\'avantage. C\'est pour ça que je trace en premier.',
      'id': 'Di permainan ini, pemain kedua yang diuntungkan. Makanya aku yang gambar duluan.',
      'vi': 'Trò này người đi sau có lợi thế. Vì vậy tớ mới vẽ trước.',
    },
    'nb_w11_title': {
      'en': 'Counting lives',
      'ko': '생명 세기',
      'ja': '命を数える',
      'zh': '数生命',
      'es': 'Contar vidas',
      'pt': 'Contando vidas',
      'de': 'Leben zählen',
      'fr': 'Compter les vies',
      'id': 'Menghitung nyawa',
      'vi': 'Đếm mạng sống',
    },
    'nb_w11_1': {
      'en': 'Each dot takes 3 lines. Count the remaining "lives".',
      'ko': '점 하나는 선 3개까지. 남은 \'생명\'을 세.',
      'ja': '点一つは線3本まで。残った「命」を数えて。',
      'zh': '一个点最多接3条线。数一数剩下的"生命"。',
      'es': 'Cada punto aguanta hasta 3 líneas. Cuenta las "vidas" que quedan.',
      'pt': 'Cada ponto aguenta até 3 linhas. Conte as "vidas" que restam.',
      'de': 'Jeder Punkt verträgt bis zu 3 Linien. Zähl die übrigen „Leben".',
      'fr': 'Chaque point supporte jusqu\'à 3 lignes. Compte les « vies » restantes.',
      'id': 'Satu titik menampung sampai 3 garis. Hitung "nyawa" yang tersisa.',
      'vi': 'Mỗi điểm chịu được tối đa 3 đường. Hãy đếm số "mạng sống" còn lại.',
    },
    'nb_w11_2': {
      'en': 'A new dot adds one life. That\'s why the board grows.',
      'ko': '새 점은 생명을 하나 더해. 그래서 판이 늘어나.',
      'ja': '新しい点は命を一つ増やす。だから盤面が広がるの。',
      'zh': '新的点会加一条生命。所以棋盘会变大。',
      'es': 'Un punto nuevo añade una vida. Por eso el tablero crece.',
      'pt': 'Um ponto novo adiciona uma vida. Por isso o tabuleiro cresce.',
      'de': 'Ein neuer Punkt bringt ein Leben mehr. Deshalb wächst das Feld.',
