    'nb_w12_title': {
      'en': 'Building bridges',
      'ko': '다리 놓기',
      'ja': '橋を架ける',
      'zh': '架桥',
      'es': 'Construir puentes',
      'pt': 'Construindo pontes',
      'de': 'Brücken bauen',
