      'ja': '二マス空けて置く:私が一つを塞いだら、もう一つでつなぐ。',
      'zh': '隔两格放:我堵住一个,你就用另一个连上。',
      'es': 'Coloca a dos casillas de distancia: si bloqueo un enlace, tomas el otro.',
