    'st_w1_a_2': {
      'en': '…I\'ll leave a bit early tomorrow. To buy candy.',
      'ko': '…내일은 조금 일찍 나올 거야. 사탕 사러.',
      'ja': '…明日は少し早く出るよ。飴買いに。',
