    'end_w1_1': {
      'en': 'One-row Nim. You cleared it all.',
      'ko': '한 줄 님게임, 다 깼네.',
      'ja': '一列のニムゲーム、全部クリアしたね。',
      'zh': '单行取子游戏,你全通关了。',
      'es': 'El Nim de una fila. Lo has superado todo.',
      'pt': 'Nim de uma fileira. Você zerou tudo.',
