    },
    'end_w1_2': {
      'en': 'Leaving multiples. I figured that out alone in grade school.',
      'ko': '배수 남기기. 그거 내가 초등학교 때 혼자 알아낸 건데.',
      'ja': '倍数を残す。それ、私が小学校の時一人で見つけたんだけど。',
