    'end_w1_4': {
      'en': 'Still, now there\'s someone to play on the way to school.',
      'ko': '그래도 이제 등교길엔 상대가 있으니까.',
      'ja': 'でも、もう登校路には相手がいるから。',
      'zh': '不过现在上学路上总算有对手了。',
      'es': 'Aun así, ahora tengo con quién jugar de camino a la escuela.',
