    'end_w1_5': {
      'en': 'Come to the rooftop at lunch. I\'ll bring chocolate.',
      'ko': '점심시간에 옥상으로 와. 초콜릿 가져갈게.',
      'ja': '昼休みに屋上に来て。チョコレート持っていくから。',
      'zh': '午休时间来天台。我带巧克力去。',
