    'end_w1_6': {
      'en': '…Be late and I eat it alone.',
      'ko': '…늦으면 혼자 먹는다.',
      'ja': '…遅れたら一人で食べるから。',
      'zh': '……迟到的话我就自己吃掉。',
      'es': '…Si llegas tarde, me lo como sola.',
      'pt': '…Se atrasar, eu como sozinha.',
