    'st_w2_a_1': {
      'en': 'The rooftop used to be my place alone.',
      'ko': '옥상은 원래 나 혼자 오는 곳이었는데.',
      'ja': '屋上はもともと私一人の場所だったのに。',
      'zh': '天台本来是我一个人的地方。',
      'es': 'La azotea solía ser mi lugar, solo mío.',
      'pt': 'O terraço costumava ser só meu.',
      'de': 'Das Dach war eigentlich mein ganz eigener Ort.',
      'fr': 'Le toit, c\'était mon endroit à moi toute seule, avant.',
      'id': 'Dulu atap ini tempatku sendirian.',
      'vi': 'Sân thượng vốn là chỗ chỉ mình tớ hay lên.',
    },
    'st_w2_a_2': {
      'en': 'The wind whispers answers up here. It seems to whisper to you too. Annoying.',
      'ko': '바람이 답을 알려주는 느낌이라. 너한테도 알려주는 것 같아서 얄미워.',
      'ja': '風が答えを教えてくれる感じがして。君にも教えてるみたいで、ちょっとムカつく。',
      'zh': '感觉风会告诉我答案。看起来它也告诉了你,真讨厌。',
      'es': 'Siento que el viento me susurra las respuestas aquí arriba. Parece que a ti también te las susurra. Qué fastidio.',
      'pt': 'Sinto que o vento sussurra as respostas aqui em cima. Parece que sussurra pra você também. Que chato.',
      'de': 'Hier oben scheint der Wind einem die Antworten zuzuflüstern. Sieht aus, als würde er es dir auch zuflüstern. Nervig.',
      'fr': 'On dirait que le vent murmure les réponses ici. Il semble te les murmurer à toi aussi. Agaçant.',
      'id': 'Rasanya angin di sini membisikkan jawaban. Sepertinya membisikkannya ke kamu juga. Menyebalkan.',
      'vi': 'Cảm giác như gió ở đây thì thầm đáp án vậy. Có vẻ nó cũng thì thầm với cậu nữa. Ghét thật.',
