    'end_w5_5': {
      'en': '…That was about math. Nothing else.',
      'ko': '…방금 건 수학 얘기야. 다른 뜻 없어.',
      'ja': '…今のは数学の話。他意はない。',
      'zh': '……刚才说的是数学的事。没有别的意思。',
      'es': '…Eso era sobre matemáticas. Nada más.',
      'pt': '…Isso foi sobre matemática. Nada além disso.',
      'de': '…Das war über Mathe. Nichts weiter.',
      'fr': '…C\'était à propos des maths. Rien d\'autre.',
      'id': '…Yang tadi soal matematika. Tidak ada maksud lain.',
      'vi': '…Vừa nãy là chuyện toán học thôi. Không có ý gì khác đâu.',
    },
    'end_w5_6': {
      'en': 'Come to the science lab. I\'ll tell you about the golden ratio.',
      'ko': '과학실로 와. 황금비 얘기 해줄게.',
      'ja': '理科室に来て。黄金比の話してあげる。',
      'zh': '来科学实验室。我跟你讲讲黄金比例。',
      'es': 'Ven al laboratorio de ciencias. Te hablaré de la proporción áurea.',
      'pt': 'Venha ao laboratório de ciências. Vou te contar sobre a proporção áurea.',
      'de': 'Komm ins Wissenschaftslabor. Ich erzähl dir vom Goldenen Schnitt.',
      'fr': 'Viens au labo de sciences. Je te parlerai du nombre d\'or.',
      'id': 'Datang ke lab sains. Aku akan cerita soal rasio emas.',
      'vi': 'Đến phòng thí nghiệm khoa học đi. Tớ sẽ kể cho nghe về tỷ lệ vàng.',
    },
    'st_w6_a_1': {
      'en': 'The lab smells. Let\'s finish fast… actually, one more.',
      'ko': '과학실 냄새 나. 빨리 끝내자… 는 아니고 한 판 더.',
      'ja': '理科室の匂いがする。早く終わらせよう…じゃなくて、もう一戦。',
      'zh': '实验室有味道。赶紧结束吧……不,再来一局。',
      'es': 'El laboratorio huele raro. Terminemos rápido… no, mejor una más.',
      'pt': 'O laboratório tem um cheiro. Vamos terminar logo… não, mais uma.',
      'de': 'Das Labor riecht komisch. Lass uns schnell fertig werden… nein, doch noch eine Runde.',
      'fr': 'Le labo sent bizarre. Finissons vite… non, encore une manche.',
      'id': 'Lab sains ini bau. Ayo cepat selesai… ah bukan, satu ronde lagi.',
      'vi': 'Phòng thí nghiệm có mùi. Xong nhanh đi… à không, chơi thêm ván nữa.',
    },
    'st_w6_a_2': {
      'en': 'Know the golden ratio? 1.618. Nature\'s favorite number.',
      'ko': '황금비 알아? 1.618. 자연이 좋아하는 숫자.',
      'ja': '黄金比知ってる? 1.618。自然が好む数字。',
      'zh': '你知道黄金比例吗?1.618。大自然偏爱的数字。',
      'es': '¿Conoces la proporción áurea? 1.618. El número favorito de la naturaleza.',
      'pt': 'Conhece a proporção áurea? 1,618. O número favorito da natureza.',
      'de': 'Kennst du den Goldenen Schnitt? 1,618. Die Lieblingszahl der Natur.',
      'fr': 'Tu connais le nombre d\'or? 1,618. Le chiffre préféré de la nature.',
      'id': 'Kamu tahu rasio emas? 1.618. Angka favorit alam.',
      'vi': 'Cậu biết tỷ lệ vàng không? 1.618. Con số mà tự nhiên ưa thích.',
    },
    'mid_w6_title': {
      'en': 'The golden ratio',
      'ko': '황금비',
      'ja': '黄金比',
      'zh': '黄金比例',
