      'ko': '위토프의 지는 자리는 (1,2) (3,5) (4,7)…',
      'ja': 'ウィトフの負けポジションは(1,2) (3,5) (4,7)…',
      'zh': '威佐夫游戏的必败点是(1,2) (3,5) (4,7)……',
      'es': 'Las posiciones perdedoras de Wythoff: (1,2) (3,5) (4,7)…',
      'pt': 'As posições perdedoras de Wythoff: (1,2) (3,5) (4,7)…',
      'de': 'Wythoffs Verlustpositionen: (1,2) (3,5) (4,7)…',
      'fr': 'Les positions perdantes de Wythoff : (1,2) (3,5) (4,7)…',
      'id': 'Posisi kalah Wythoff: (1,2) (3,5) (4,7)…',
      'vi': 'Các vị trí thua trong trò Wythoff: (1,2) (3,5) (4,7)…',
    },
    'mid_w6_2': {
      'en': 'The small pile is a multiple of the golden ratio, rounded down.',
      'ko': '작은 쪽이 황금비의 배수를 내림한 값이야.',
      'ja': '小さい方は黄金比の倍数を切り捨てた値。',
      'zh': '较小的那堆是黄金比例倍数的向下取整值。',
      'es': 'El montón pequeño es un múltiplo de la proporción áurea, redondeado hacia abajo.',
      'pt': 'A pilha menor é um múltiplo da proporção áurea, arredondado pra baixo.',
      'de': 'Der kleinere Stapel ist ein abgerundetes Vielfaches des Goldenen Schnitts.',
      'fr': 'Le petit tas est un multiple du nombre d\'or, arrondi vers le bas.',
      'id': 'Tumpukan yang lebih kecil adalah kelipatan rasio emas yang dibulatkan ke bawah.',
      'vi': 'Đống nhỏ hơn là bội số của tỷ lệ vàng, làm tròn xuống.',
    },
    'mid_w6_3': {
      'en': 'Sunflowers, seashells, this game — same number.',
      'ko': '해바라기도, 조개도, 이 게임도 같은 숫자를 써.',
      'ja': 'ひまわりも、貝殻も、このゲームも同じ数字を使う。',
      'zh': '向日葵也好,贝壳也好,这个游戏也好,用的是同一个数字。',
      'es': 'Los girasoles, las conchas, este juego… el mismo número.',
      'pt': 'Girassóis, conchas, esse jogo… o mesmo número.',
      'de': 'Sonnenblumen, Muscheln, dieses Spiel — dieselbe Zahl.',
      'fr': 'Les tournesols, les coquillages, ce jeu — le même chiffre.',
      'id': 'Bunga matahari, kerang, permainan ini — semuanya pakai angka yang sama.',
      'vi': 'Hoa hướng dương, vỏ sò, cả trò chơi này nữa — đều dùng chung một con số.',
    },
    'mid_w6_4': {
      'en': '…Your moves are that pretty sometimes. Mathematically.',
      'ko': '…네가 두는 수도 가끔 그렇게 예뻐. 수학적으로.',
      'ja': '…君が打つ手も、たまにそんな風にきれい。数学的に。',
      'zh': '……你下的棋有时候也是这样美。从数学上来说。',
      'es': '…A veces tus jugadas son así de bonitas. Matemáticamente.',
      'pt': '…Suas jogadas às vezes são assim, bonitas. Matematicamente.',
      'de': '…Deine Züge sind manchmal genauso schön. Mathematisch gesehen.',
      'fr': '…Tes coups sont parfois aussi beaux que ça. Mathématiquement parlant.',
      'id': '…Langkahmu kadang secantik itu juga. Secara matematis.',
      'vi': '…Nước đi của cậu đôi khi cũng đẹp như vậy đấy. Về mặt toán học.',
    },
    'st_w6_b_1': {
      'en': 'Your logic has holes like a donut… no, it doesn\'t. Not today.',
      'ko': '도넛 구멍처럼 네 논리엔 빈틈이… 없네. 오늘은.',
      'ja': 'ドーナツの穴みたいに君の論理には隙が…ないね。今日は。',
      'zh': '像甜甜圈的洞一样,你的逻辑有漏洞……没有呢。今天。',
      'es': 'Tu lógica tiene agujeros como una dona… no, no los tiene. Hoy no.',
      'pt': 'Sua lógica tem buracos igual a rosquinha… não tem, não. Hoje não.',
      'de': 'Deine Logik hat Löcher wie ein Donut… nein, hat sie nicht. Heute nicht.',
      'fr': 'Ta logique a des trous comme un donut… non, elle n\'en a pas. Pas aujourd\'hui.',
      'id': 'Logikamu berlubang seperti donat… tidak, nggak ada lubangnya. Hari ini.',
      'vi': 'Logic của cậu có lỗ hổng như bánh donut… à không, chẳng có đâu. Hôm nay thì không.',
    },
    'st_w6_b_2': {
      'en': 'Maybe tomorrow. I\'ll be waiting.',
      'ko': '내일은 있을지도. 기대할게.',
      'ja': '明日はあるかもね。楽しみにしてる。',
      'zh': '说不定明天会有。我很期待。',
      'es': 'Puede que mañana sí. Lo esperaré.',
      'pt': 'Talvez amanhã. Vou esperar por isso.',
      'de': 'Vielleicht morgen. Ich freu mich drauf.',
      'fr': 'Peut-être demain. J\'attendrai ça avec impatience.',
      'id': 'Mungkin besok ada. Aku akan menantikannya.',
      'vi': 'Có khi mai sẽ có. Tớ sẽ mong chờ đấy.',
    },
    'end_w6_title': {
      'en': 'Numbers in the lab',
      'ko': '과학실의 숫자',
      'ja': '理科室の数字',
      'zh': '实验室的数字',
      'es': 'Números en el laboratorio',
      'pt': 'Números no laboratório',
      'de': 'Zahlen im Labor',
