    'end_w6_1': {
      'en': 'Wythoff, cleared. You learned the golden ratio by hand.',
      'ko': '위토프까지 다 깼어. 황금비를 손으로 익힌 거야.',
      'ja': 'ウィトフまで全部クリアした。黄金比を手で覚えたんだね。',
      'zh': '连威佐夫也通关了。你是用手学会了黄金比例。',
      'es': 'Wythoff, superado. Aprendiste la proporción áurea con tus propias manos.',
      'pt': 'Wythoff, zerado. Você aprendeu a proporção áurea na prática.',
      'de': 'Wythoff, geschafft. Du hast den Goldenen Schnitt mit den eigenen Händen gelernt.',
      'fr': 'Wythoff, terminé. Tu as appris le nombre d\'or de tes propres mains.',
      'id': 'Wythoff, tuntas. Kamu belajar rasio emas lewat tanganmu sendiri.',
      'vi': 'Wythoff cũng phá đảo rồi. Cậu học được tỷ lệ vàng bằng chính đôi tay mình đấy.',
    },
    'end_w6_2': {
      'en': 'I always found numbers easier than people. Numbers don\'t betray you.',
      'ko': '나는 숫자가 사람보다 편했어. 숫자는 배신 안 하니까.',
      'ja': '私は数字の方が人より楽だった。数字は裏切らないから。',
      'zh': '对我来说数字比人更轻松。因为数字不会背叛。',
      'es': 'Para mí, los números siempre fueron más fáciles que las personas. Los números no traicionan.',
      'pt': 'Pra mim, números sempre foram mais fáceis que pessoas. Números não traem.',
      'de': 'Zahlen waren mir immer angenehmer als Menschen. Zahlen verraten einen nicht.',
      'fr': 'Pour moi, les chiffres étaient plus faciles que les gens. Les chiffres ne trahissent pas.',
      'id': 'Bagiku angka selalu lebih mudah daripada orang. Karena angka tidak berkhianat.',
      'vi': 'Với tớ số liệu lúc nào cũng dễ chịu hơn con người. Vì số liệu không phản bội ai cả.',
    },
    'end_w6_3': {
      'en': 'But you play differently every time and still land on the right spot.',
      'ko': '근데 너는 매번 다르게 두면서도 결국 맞는 자리로 와.',
      'ja': 'でも君は毎回違う手を打つのに、結局正しい場所に来る。',
      'zh': '可你每次下法都不一样,却总能走到正确的位置。',
      'es': 'Pero tú juegas distinto cada vez y aun así llegas al lugar correcto.',
      'pt': 'Mas você joga diferente toda vez e mesmo assim chega no lugar certo.',
      'de': 'Aber du spielst jedes Mal anders und landest trotzdem am richtigen Punkt.',
      'fr': 'Mais toi, tu joues différemment à chaque fois et tu finis quand même au bon endroit.',
      'id': 'Tapi kamu selalu bermain berbeda tiap kali, tapi tetap sampai ke posisi yang benar.',
      'vi': 'Nhưng cậu lần nào cũng đi khác nhau mà cuối cùng vẫn đến đúng vị trí.',
    },
    'end_w6_4': {
      'en': 'Maybe that\'s the difference between people and numbers.',
      'ko': '그게 사람이랑 숫자의 차이인가 봐.',
      'ja': 'それが人と数字の違いなのかも。',
      'zh': '也许这就是人和数字的区别吧。',
      'es': 'Quizás esa es la diferencia entre las personas y los números.',
      'pt': 'Talvez essa seja a diferença entre pessoas e números.',
      'de': 'Vielleicht ist das der Unterschied zwischen Menschen und Zahlen.',
      'fr': 'C\'est peut-être ça, la différence entre les gens et les chiffres.',
      'id': 'Mungkin itulah bedanya orang dengan angka.',
      'vi': 'Có lẽ đó là khác biệt giữa con người và số liệu.',
    },
    'end_w6_5': {
      'en': '…There\'s a rabbit hutch out back. Some of them need names.',
      'ko': '…뒤뜰에 토끼장 있어. 이름 지어줄 애들이 있거든.',
      'ja': '…裏庭にウサギ小屋があるの。名前をつけてあげる子たちがいて。',
      'zh': '……后院有兔笼。有几只还没起名字。',
      'es': '…Hay una conejera atrás. Algunos necesitan nombre.',
      'pt': '…Tem uma coelheira nos fundos. Alguns precisam de nome.',
      'de': '…Hinten gibt es einen Kaninchenstall. Ein paar brauchen noch Namen.',
      'fr': '…Il y a un clapier derrière. Certains ont besoin d\'un nom.',
      'id': '…Ada kandang kelinci di belakang. Ada beberapa yang perlu diberi nama.',
      'vi': '…Có chuồng thỏ ở sân sau đấy. Có vài con cần đặt tên.',
    },
    'end_w6_6': {
