      'fr': 'Viens avec moi. Apporte des bonbons gélifiés.',
      'id': 'Ayo bareng. Bawa permen jeli.',
      'vi': 'Đi cùng tớ đi. Mang kẹo dẻo theo nhé.',
    },
    'st_w7_a_1': {
      'en': 'Even the rabbits cheered for you. Traitors.',
      'ko': '토끼도 너 응원하더라. 배신자들.',
      'ja': 'ウサギまで君を応援してた。裏切り者ども。',
      'zh': '连兔子都在给你加油。叛徒们。',
      'es': 'Hasta los conejos te animaban. Traidores.',
      'pt': 'Até os coelhos torciam por você. Traidores.',
      'de': 'Sogar die Kaninchen haben dich angefeuert. Verräter.',
