    'mid_w7_2': {
      'en': '…Don\'t laugh. I was serious.',
      'ko': '…웃지 마. 진지하게 지은 거야.',
      'ja': '…笑うな。真剣に考えたんだから。',
      'zh': '……别笑。我是认真取的。',
      'es': '…No te rías. Lo hice en serio.',
