    },
    'mid_w7_3': {
      'en': 'Fibonacci numbers came from counting rabbits. That\'s why.',
      'ko': '피보나치 수는 토끼 세는 데서 나왔대. 그래서.',
      'ja': 'フィボナッチ数はウサギを数えるところから生まれたんだって。だから。',
