    'end_w7_4': {
      'en': '…Twenty rounds, seven times. A hundred and forty. I was counting.',
      'ko': '…스무 판씩 일곱 번. 백사십 판. 세고 있었어.',
      'ja': '…二十戦ずつ七回。百四十戦。数えてたんだ。',
      'zh': '……二十局乘七次。一百四十局。我一直在数。',
      'es': '…Veinte rondas, siete veces. Ciento cuarenta. Llevaba la cuenta.',
