      'fr': 'On est sûr de gagner sans savoir comment. Bizarre, non ?',
      'id': 'Pasti menang tapi nggak tahu caranya. Aneh, kan?',
      'vi': 'Chắc chắn thắng mà lại không biết cách. Lạ nhỉ.',
    },
    'mid_w8_3': {
