      'vi': 'Đến phòng câu lạc bộ đi. Trò chơi né hình tam giác đấy.',
    },
    'end_w9_6': {
      'en': 'In that game I draw one line first. It\'s a rule. …No, it\'s an excuse.',
      'ko': '그 게임은 내가 먼저 한 줄 긋고 시작해. 규칙이야. …아니, 핑계야.',
      'ja': 'あのゲームは私が先に一本引いてから始める。ルールだから。…いや、言い訳。',
      'zh': '那个游戏我先画一条线才开始。是规则。……不,是借口。',
      'es': 'En ese juego, yo trazo una línea primero. Es la regla. …No, es una excusa.',
      'pt': 'Nesse jogo eu traço uma linha primeiro. É a regra. …Não, é desculpa.',
      'de': 'Bei dem Spiel zieh ich zuerst eine Linie. Das ist die Regel. …Nein, ein Vorwand.',
      'fr': 'Dans ce jeu, je trace d\'abord une ligne. C\'est la règle. …Non, c\'est une excuse.',
      'id': 'Di permainan itu aku menggambar satu garis duluan. Itu aturannya. …Bukan, itu alasan saja.',
      'vi': 'Trò đó tớ vẽ một đường trước rồi mới bắt đầu. Là luật đấy. …Không, là cái cớ thôi.',
    },
    'st_w10_a_1': {
